def validate(model, loader):
    model.eval()
    scores = []
    with torch.no_grad():
        for x, y in loader:
            x = x.to(device)
            prob = torch.sigmoid(model(x)).cpu()
            pred = prob > 0.5
            scores.extend([binary_iou(p, t > 0.5) for p, t in zip(pred, y)])
    return sum(scores) / len(scores)
